  return `${pageTitle('Suppliers','Organize the partners who keep you stocked.',`<button class="btn btn-primary" data-action="add-supplier">${icon('plus')}Add supplier</button>`)}<section class="card table-card">${toolbar('Supplier directory',`${data.items?.length||0} active suppliers`,`<input class="search-input" data-search="suppliers" placeholder="Search suppliers">`)}<div class="table-scroll"><table>${tableHead(['Supplier / contact','Phone','Email','Address','Actions'])}<tbody>${rows}</tbody></table></div></section>`;
