export async function renderPage(path) {
  if(path==='/dashboard') return dashboardPage();
  if(path==='/products') return productsPage();
  if(path==='/inventory') return inventoryPage();
  if(path==='/sales') return salesPage();
  if(path==='/customers') return customersPage();
  if(path==='/suppliers') return suppliersPage();
  if(path==='/invoices') return invoicesPage();
  if(path==='/quotations') return quotationsPage();
  if(path==='/expenses') return expensesPage();
  if(path==='/reports') return reportsPage();
  if(path==='/staff') return staffPage();
  if(path==='/billing') return billingPage();
  if(path==='/billing/upgrade') return upgradePage();
  if(path==='/billing/history') return billingHistoryPage();
  if(path==='/settings') return settingsPage();
  if(path==='/settings/security') return securitySettingsPage();
  if(path==='/account') return accountPage();
  throw new ApiError('This page is not available.',404);
}

function formObject(form) { return Object.fromEntries(new FormData(form).entries()); }
function linesFromForm(form) {
  return [...form.querySelectorAll('.line-row')].map(row=>{
    const product_id=row.querySelector('.line-product')?.value||'';
    const name=row.querySelector('.line-name')?.value||'';
    const quantity=Number(row.querySelector('.line-qty')?.value||0);
    const unit_price=Number(row.querySelector('.line-price')?.value||0);
    return product_id?{product_id,quantity,unit_price}:{product_name:name,quantity,unit_price};
  });
}
function updateDocumentPreview(form){
  if(!form)return;
  const preview=form.querySelector('.live-document-preview');if(!preview)return;
  const get=(selector)=>preview.querySelector(selector);
  const customer=form.querySelector('[name="customer_id"]');
  const selectedCustomer=customer?.selectedOptions?.[0];
  const customerTarget=get('[data-preview-customer]');if(customerTarget)customerTarget.textContent=selectedCustomer?.value?selectedCustomer.textContent.trim():'Choose a customer';
  const issued=form.querySelector('[name="invoice_date"]');
  const secondDate=form.querySelector('[name="due_date"],[name="valid_until"]');
  const issuedTarget=get('[data-preview-issued]');if(issuedTarget)issuedTarget.textContent=issued?.value?dateFmt(issued.value):'—';
  const dateTarget=get('[data-preview-date]');if(dateTarget)dateTarget.textContent=secondDate?.value?dateFmt(secondDate.value):'—';
  const lines=[...form.querySelectorAll('.line-row')].map(row=>{
    const select=row.querySelector('.line-product');const option=select?.selectedOptions?.[0];
    const name=select?.value?(option?.dataset.name||option?.textContent?.split(' · ')[0]||'Product'):row.querySelector('.line-name')?.value?.trim();
    const quantity=Number(row.querySelector('.line-qty')?.value||0);const unitPrice=Number(row.querySelector('.line-price')?.value||0);
    return {name,quantity,unitPrice,total:quantity*unitPrice};
  }).filter(line=>line.name&&line.quantity>0);
  const subtotal=lines.reduce((sum,line)=>sum+line.total,0);
  const discount=Math.max(0,Number(form.querySelector('[name="discount"]')?.value||0));
  const total=Math.max(0,subtotal-discount);
  const rows=get('[data-preview-rows]');
  if(rows)rows.innerHTML=lines.length?lines.map(line=>`<tr><td>${esc(line.name)}</td><td>${line.quantity.toLocaleString('en-LK',{maximumFractionDigits:3})}</td><td>${money(line.total)}</td></tr>`).join(''):'<tr><td colspan="3" class="live-preview-empty">Add an item to preview the total.</td></tr>';
  const subtotalTarget=get('[data-preview-subtotal]');if(subtotalTarget)subtotalTarget.textContent=money(subtotal);
  const discountRow=get('[data-preview-discount-row]');if(discountRow)discountRow.hidden=discount===0;
  const discountTarget=get('[data-preview-discount]');if(discountTarget)discountTarget.textContent=`−${money(discount)}`;
  const totalTarget=get('[data-preview-total]');if(totalTarget)totalTarget.textContent=money(total);
  const paidField=form.querySelector('[name="paid_amount"]');const paid=paidField?Math.max(0,Number(paidField.value||0)):Number(preview.dataset.existingPaid||0);
  const paidTarget=get('[data-preview-paid]');if(paidTarget)paidTarget.textContent=money(paid);
  const balanceTarget=get('[data-preview-balance]');if(balanceTarget)balanceTarget.textContent=money(Math.max(0,total-paid));
  const notes=form.querySelector('textarea[name="notes"],input[name="notes"]');const noteTarget=get('[data-preview-notes]');
  if(noteTarget){noteTarget.hidden=!notes?.value?.trim();noteTarget.textContent=notes?.value?.trim()||'';}
}

export async function handleAction(action, el) {
  const id=el.dataset.id;
  if(action==='close-modal'){closeModal();return true;}
  if(action==='add-product'){let suppliers=[];try{suppliers=(await api('/api/suppliers')).items||[];}catch{} modal('Add product','Product and stock information',productForm({},suppliers));return true;}
  if(action==='edit-product') {const row=(await api('/api/products')).items.find(p=>p.id===id);if(!row)throw new Error('Product not found.');let suppliers=[];try{suppliers=(await api('/api/suppliers')).items||[];}catch{}modal('Edit product','Changes to quantity are recorded as a stock adjustment.',productForm(row,suppliers));return true;}
  if(action==='delete-product'){modal('Archive this product?','The product will be removed from active lists. Historical sales remain unchanged.',`<p class="support-stat">You can no longer select this product for new sales, but existing invoices and reports will keep their snapshots.</p>`,`<button class="btn btn-ghost" data-action="close-modal">Keep product</button><button class="btn btn-danger" data-action="confirm-delete-product" data-id="${esc(id)}">Archive product</button>`);return true;}
  if(action==='confirm-delete-product'){await api(`/api/products/${encodeURIComponent(id)}`,{method:'DELETE'});closeModal();toast('Product archived.');refresh();return true;}
  if(action==='adjust-stock'){const p=(await api('/api/products')).items.find(x=>x.id===id);if(!p)throw new Error('Product not found.');modal('Adjust inventory','The adjustment will be recorded in the stock movement history.',productStockForm(p));return true;}
  if(action==='go-sales'){navigate('/sales');return true;}
  if(action==='cart-add'){const p=(await api('/api/products')).items.find(x=>x.id===id);if(!p)return true;let item=state.cart.find(x=>x.id===id);if(item){if(item.quantity<Number(p.quantity))item.quantity++;else toast('That is all the available stock.','warning');}else state.cart.push({id:p.id,name:p.name,price:Number(p.selling_price),quantity:1,available:Number(p.quantity)});refresh();return true;}
  if(action==='cart-plus'){const i=state.cart.find(x=>x.id===id);if(i&&i.quantity<i.available)i.quantity++;else toast('That is all the available stock.','warning');refresh();return true;}
  if(action==='cart-minus'){const i=state.cart.find(x=>x.id===id);if(i){i.quantity--;if(i.quantity<=0)state.cart=state.cart.filter(x=>x.id!==id);}refresh();return true;}
  if(action==='cart-remove'){state.cart=state.cart.filter(x=>x.id!==id);refresh();return true;}
  if(action==='cart-clear'){state.cart=[];refresh();return true;}
  if(action==='add-customer'){modal('Add customer','A customer profile can be linked to sales and invoices.',customerForm());return true;}
  if(action==='edit-customer'){const c=await api(`/api/customers/${encodeURIComponent(id)}`);modal('Edit customer','Update this business contact.',customerForm(c.customer));return true;}
  if(action==='delete-customer'){modal('Archive customer?','This hides the contact from new lists while preserving its history.',`<p class="support-stat">Existing sales and invoices remain linked to the customer.</p>`,`<button class="btn btn-ghost" data-action="close-modal">Cancel</button><button class="btn btn-danger" data-action="confirm-delete-customer" data-id="${esc(id)}">Archive customer</button>`);return true;}
  if(action==='confirm-delete-customer'){await api(`/api/customers/${encodeURIComponent(id)}`,{method:'DELETE'});closeModal();toast('Customer archived.');refresh();return true;}
  if(action==='view-customer'){const d=await api(`/api/customers/${encodeURIComponent(id)}`);const c=d.customer;const sales=d.sales?.length?d.sales.map(s=>`<tr><td>${esc(s.sale_number)}</td><td>${dateFmt(s.created_at)}</td><td>${badge(s.status)}</td><td>${money(s.total)}</td></tr>`).join(''):emptyRow(4,'No sales yet','Customer purchases will show here.');modal(c.name,'Customer profile and purchase summary',`<div class="content-grid grid-3" style="margin-bottom:14px">${stat('Purchases',money(d.total_purchases),'Recorded sales','bag')}${stat('Outstanding',money(d.outstanding_balance),'Sales balance','wallet')}${stat('Invoices',d.invoices?.length||0,'All dates','receipt')}</div><div class="kv-list"><div class="kv"><span>Phone</span><strong>${esc(c.phone||'—')}</strong></div><div class="kv"><span>Email</span><strong>${esc(c.email||'—')}</strong></div><div class="kv"><span>Address</span><strong>${esc(c.address||'—')}</strong></div></div><div class="table-scroll" style="margin-top:16px"><table>${tableHead(['Sale','Date','Status','Total'])}<tbody>${sales}</tbody></table></div>`);return true;}
  if(action==='add-supplier'){modal('Add supplier','Keep your supplier contact details in one place.',supplierForm());return true;}
  if(action==='view-supplier'){const d=await api(`/api/suppliers/${encodeURIComponent(id)}`);const products=d.products?.length?d.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.sku)}</td><td>${Number(p.quantity).toLocaleString()}</td><td>${money(p.purchase_price)}</td></tr>`).join(''):emptyRow(4,'No linked products','Products linked to this supplier will appear here.');const purchases=d.purchase_history?.length?d.purchase_history.map(p=>`<tr><td>${dateFmt(p.created_at,true)}</td><td>${esc(p.product_name)}</td><td>+${Number(p.quantity_delta).toLocaleString()}</td><td>${esc(p.reason||'—')}</td></tr>`).join(''):emptyRow(4,'No purchase movements','Record a Purchase stock movement on a linked product to see it here.');modal(d.supplier.name,'Supplier contact and linked stock history',`<div class="kv-list"><div class="kv"><span>Contact</span><strong>${esc(d.supplier.contact_person||'—')}</strong></div><div class="kv"><span>Phone</span><strong>${esc(d.supplier.phone||'—')}</strong></div><div class="kv"><span>Email</span><strong>${esc(d.supplier.email||'—')}</strong></div></div><h3 style="font-size:12px;margin:18px 0 7px">Products supplied</h3><div class="table-scroll"><table>${tableHead(['Product','SKU','On hand','Cost'])}<tbody>${products}</tbody></table></div><h3 style="font-size:12px;margin:18px 0 7px">Purchase history</h3><div class="table-scroll"><table>${tableHead(['Date','Product','Units received','Reason'])}<tbody>${purchases}</tbody></table></div>`);return true;}
  if(action==='edit-supplier'){const item=(await api('/api/suppliers')).items.find(s=>s.id===id);if(!item)throw new Error('Supplier not found.');modal('Edit supplier','Update contact information.',supplierForm(item));return true;}
  if(action==='delete-supplier'){modal('Archive supplier?','Historical stock and product information remain saved.',`<p class="support-stat">This supplier will no longer appear as an active contact.</p>`,`<button class="btn btn-ghost" data-action="close-modal">Cancel</button><button class="btn btn-danger" data-action="confirm-delete-supplier" data-id="${esc(id)}">Archive supplier</button>`);return true;}
  if(action==='confirm-delete-supplier'){await api(`/api/suppliers/${encodeURIComponent(id)}`,{method:'DELETE'});closeModal();toast('Supplier archived.');refresh();return true;}
  if(action==='add-invoice'){await documentModal('invoice');return true;}
  if(action==='edit-invoice'){await documentModal('invoice',id);return true;}
  if(action==='add-quotation'){await documentModal('quotation');return true;}
  if(action==='edit-quotation'){await documentModal('quotation',id);return true;}
  if(action==='mark-quotation-sent'){await api(`/api/quotations/${encodeURIComponent(id)}/status`,{method:'POST',body:{status:'SENT'}});toast('Quotation marked as sent.');refresh();return true;}
  if(action==='view-invoice'){await showInvoice(id);return true;}
  if(action==='view-quotation'){await showQuotation(id);return true;}
  if(action==='add-document-line'){const form=el.closest('.modal')?.querySelector('form');if(!form)return true;const kind=form.dataset.kind;const products=(await api('/api/products')).items||[];form.querySelector('.document-lines').insertAdjacentHTML('beforeend',lineRow(products));updateDocumentPreview(form);return true;}
  if(action==='remove-line'){const row=el.closest('.line-row');const form=el.closest('form');if(formLineCount(form)>1){row.remove();updateDocumentPreview(form);}else toast('A document needs at least one line.','warning');return true;}
  if(action==='invoice-payment'){await invoicePaymentModal(id);return true;}
  if(action==='locked-feature'){await api(`/api/features/${encodeURIComponent(el.dataset.feature)}`);return true;}
  if(action==='print-invoice'){await api('/api/features/pdf_invoices');window.print();return true;}
  if(action==='share-invoice'){await api('/api/features/whatsapp_sharing');const d=await api(`/api/invoices/${encodeURIComponent(id)}`);const i=d.invoice;const status=i.balance>0?`Balance due ${money(i.balance)}`:'Paid';const text=`${state.business?.business_name||'Business'} — Invoice ${i.invoice_number} for ${i.customer_name}. Amount ${money(i.total)}. ${status}.`;window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank','noopener');return true;}
  if(action==='convert-quotation'){if(!confirm('Convert this quotation into an invoice? This will create an invoice and mark the quotation Accepted.'))return true;const result=await api(`/api/quotations/${encodeURIComponent(id)}/convert`,{method:'POST',body:{}});closeModal();toast(result.already_converted?'This quote already has an invoice.':'Quotation converted to invoice.');navigate('/invoices');return true;}
  if(action==='add-expense'){modal('Add expense','Record a cost for this business.',expenseForm());return true;}
  if(action==='delete-expense'){if(!confirm('Remove this expense record?'))return true;await api(`/api/expenses/${encodeURIComponent(id)}`,{method:'DELETE'});toast('Expense removed.');refresh();return true;}
  if(action==='report-tab'){navigate(`/reports?type=${encodeURIComponent(el.dataset.type)}`);return true;}
  if(action==='apply-report'){const form=el.closest('section')?.querySelector('input[name=report_from]');const to=el.closest('section')?.querySelector('input[name=report_to]');const type=document.querySelector('[name=report_type]')?.value||'sales';navigate(`/reports?type=${type}&period=custom&from_date=${form?.value||''}&to_date=${to?.value||''}`);return true;}
  if(action==='add-staff'){modal('Add team member','Create an account scoped to this business.',staffForm());return true;}
  if(action==='edit-staff'){modal('Change team role','Roles control access on the server.',`<form class="form-stack" data-form="staff-role"><input type="hidden" name="id" value="${esc(id)}"><div class="field"><label>Role</label><select name="role"><option value="STAFF" ${el.dataset.role==='STAFF'?'selected':''}>Staff</option><option value="MANAGER" ${el.dataset.role==='MANAGER'?'selected':''}>Manager</option></select></div><div class="modal-footer" style="margin:4px -21px -22px"><button type="button" class="btn btn-ghost" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save role</button></div></form>`);return true;}
  if(action==='remove-staff'){if(!confirm('Remove this team member from the business? Their account and audit history will be retained.'))return true;await api(`/api/staff/${encodeURIComponent(id)}`,{method:'DELETE'});toast('Team member removed.');refresh();return true;}
  if(action==='change-password'){navigate('/settings/security');return true;}
  if(action==='choose-plan'){const p=el.dataset.plan;if(p==='FREE'){navigate('/dashboard');return true;}navigate(`/billing/upgrade?plan=${encodeURIComponent(p)}`);return true;}
  if(action==='cancel-payment'){if(!confirm('Cancel this pending payment request?'))return true;await api(`/api/billing/payment-requests/${encodeURIComponent(id)}/cancel`,{method:'POST',body:{}});toast('Payment request cancelled.');refresh();return true;}
  if(action==='history'){navigate('/billing/history');return true;}
  if(action==='retry-page'){refresh();return true;}
  if(action==='add-location'){modal('Add business location','Add a branch or shop address.',locationForm());return true;}
  if(action==='edit-location'){modal('Edit business location','Update branch details.',locationForm({id,name:el.dataset.name,address:el.dataset.address}));return true;}
  if(action==='delete-location'){if(!confirm('Remove this business location?'))return true;await api(`/api/locations/${encodeURIComponent(id)}`,{method:'DELETE'});toast('Location removed.');refresh();return true;}
  if(action==='settings-tab'){if(el.dataset.tab==='account')navigate('/account');else if(el.dataset.tab==='security')navigate('/settings/security');else toast('Invoice and business fields are on this settings page.','warning');return true;}
  if(action==='public-menu'){document.getElementById('public-nav')?.classList.toggle('open');return true;}
  return false;
}
function formLineCount(form){return form?.querySelectorAll('.line-row').length||0;}

export async function handleForm(form) {
  const type=form.dataset.form;
  const values=formObject(form);
  if(type==='product'){
    const id=values.id;const image=form.querySelector('[name=image]')?.files?.[0];delete values.id;delete values.image;values.supplier_id=values.supplier_id||null;
    const out=await api(id?`/api/products/${encodeURIComponent(id)}`:'/api/products',{method:id?'PUT':'POST',body:values});
    const productId=id||out.id;
    if(image){const fd=new FormData();fd.append('image',image);try{await api(`/api/products/${encodeURIComponent(productId)}/image`,{method:'POST',body:fd});}catch(error){if(!id){const key=form.querySelector('[name=id]');if(key)key.value=productId;}throw error;}}
    closeModal();toast(out.message||'Product saved.');refresh();return true;
  }
  if(type==='adjust-stock'){const id=values.id;delete values.id;const out=await api(`/api/inventory/${encodeURIComponent(id)}/adjust`,{method:'POST',body:values});closeModal();toast(`Inventory is now ${Number(out.quantity).toLocaleString()}.`);refresh();return true;}
  if(type==='sale'){
    if(!state.cart.length)throw new Error('Add a product to the sale first.');
    const payload={customer_id:values.customer_id||null,payment_method:values.payment_method,discount:Number(values.discount||0),paid_amount:Number(values.paid_amount||0),items:state.cart.map(x=>({product_id:x.id,quantity:Number(x.quantity)}))};
    const out=await api('/api/sales',{method:'POST',body:payload});state.cart=[];toast(`Sale ${out.sale_number} recorded.`);refresh();return true;
  }
  if(type==='customer'){
    const id=values.id;delete values.id;const out=await api(id?`/api/customers/${encodeURIComponent(id)}`:'/api/customers',{method:id?'PUT':'POST',body:values});closeModal();toast(out.message||'Customer saved.');refresh();return true;
  }
  if(type==='supplier'){
    const id=values.id;delete values.id;const out=await api(id?`/api/suppliers/${encodeURIComponent(id)}`:'/api/suppliers',{method:id?'PUT':'POST',body:values});closeModal();toast(out.message||'Supplier saved.');refresh();return true;
  }
  if(type==='invoice'||type==='quotation'){
    const id=values.id;delete values.id;values.items=linesFromForm(form);values.customer_id=values.customer_id||null;
    if(type==='invoice'&&!id)values.paid_amount=Number(values.paid_amount||0);
    const out=await api(type==='invoice'?(id?`/api/invoices/${encodeURIComponent(id)}`:'/api/invoices'):(id?`/api/quotations/${encodeURIComponent(id)}`:'/api/quotations'),{method:id?'PUT':'POST',body:values});closeModal();toast(`${type==='invoice'?'Invoice':'Quotation'} ${id?'updated':'created'}${out.invoice_number?`: ${out.invoice_number}`:out.quotation_number?`: ${out.quotation_number}`:''}.`);refresh();return true;
  }
  if(type==='invoice-payment'){
    const id=values.id;delete values.id;const out=await api(`/api/invoices/${encodeURIComponent(id)}/payments`,{method:'POST',body:values});closeModal();toast(`Payment saved. Balance: ${money(out.balance)}.`);refresh();return true;
  }
  if(type==='location'){
    const id=values.id;delete values.id;await api(id?`/api/locations/${encodeURIComponent(id)}`:'/api/locations',{method:id?'PUT':'POST',body:values});closeModal();toast(id?'Location updated.':'Location added.');refresh();return true;
  }
  if(type==='expense'){
    const file=form.querySelector('[name=receipt]')?.files?.[0];delete values.receipt;
    const out=await api('/api/expenses',{method:'POST',body:values});
    if(file){const fd=new FormData();fd.append('receipt',file);try{await api(`/api/expenses/${encodeURIComponent(out.id)}/receipt`,{method:'POST',body:fd});}catch(error){try{await api(`/api/expenses/${encodeURIComponent(out.id)}`,{method:'DELETE'});}catch{}throw error;}}
    closeModal();toast('Expense saved.');refresh();return true;
  }
  if(type==='staff'){
    const out=await api('/api/staff',{method:'POST',body:values});closeModal();toast('Team member created.');refresh();modal('Share temporary password','This password is shown only once. Share it securely with your team member.',`<div class="notice notice-warning">${icon('shield')}<span>BizFlow will require a password change at their first sign-in.</span></div><div class="kv-list" style="margin-top:12px"><div class="kv"><span>Username</span><strong>${esc(out.username)}</strong></div><div class="kv"><span>Account ID</span><strong>${esc(out.public_account_id)}</strong></div></div><div class="field" style="margin-top:14px"><label>Temporary password</label><input readonly value="${esc(out.temporary_password)}" id="generated-password"></div>`,`<button class="btn btn-ghost" data-action="copy-temp-password">Copy password</button><button class="btn btn-primary" data-action="close-modal">Done</button>`);return true;
  }
  if(type==='staff-role'){
    const id=values.id;delete values.id;await api(`/api/staff/${encodeURIComponent(id)}`,{method:'PUT',body:values});closeModal();toast('Team role updated.');refresh();return true;
  }
  if(type==='payment-request'){
    const file=form.querySelector('input[type=file]')?.files?.[0];if(!file)throw new Error('Choose a payment receipt to continue.');const fd=new FormData();fd.append('plan_id',values.plan_id);fd.append('receipt',file);const out=await api('/api/billing/payment-request',{method:'POST',body:fd});toast(out.message,'success');navigate('/billing');return true;
  }
  if(type==='settings'){
    const out=await api('/api/settings',{method:'PUT',body:values});toast(out.message||'Settings saved.');refresh();return true;
  }
  if(type==='account'){
    const out=await api('/api/account',{method:'PUT',body:values});toast(out.message||'Profile saved.');refresh();return true;
  }
  if(type==='change-password'){
    if(values.new_password!==values.confirm_password)throw new Error('The new passwords do not match.');const out=await api('/api/auth/change-password',{method:'POST',body:values});state.csrf=out.csrf_token||state.csrf;closeModal();toast(out.message);refresh();return true;
  }
  return false;
}

export function handleInput(el) {
  if(el.matches('[data-cart-discount]')){
    const total=cartTotal(Number(el.value||0));const sub=document.querySelector('[data-cart-subtotal]');const disc=document.querySelector('[data-cart-discount-label]');const final=document.querySelector('[data-cart-total]');if(sub)sub.textContent=money(total.subtotal);if(disc)disc.textContent=money(total.discount);if(final)final.textContent=money(total.total);const paid=document.querySelector('[name=paid_amount]');if(paid&&!paid.dataset.touched)paid.value=total.total;
  }
  if(el.matches('[data-receipt-file]')){
    const file=el.files?.[0];const form=el.closest('form');const name=form?.querySelector('[data-file-name]');const status=form?.querySelector('[data-file-status]');
    if(name)name.textContent=file?.name||'Choose a receipt';
    const tooLarge=Boolean(file&&file.size>5*1024*1024);el.setCustomValidity(tooLarge?'This receipt is larger than 5 MB. Choose a smaller file.':'');
    if(status){status.textContent=tooLarge?'This file is larger than 5 MB. Choose a smaller receipt.':file?`Ready to submit · ${(file.size/1024/1024).toFixed(2)} MB`:'Up to 5 MB. Your receipt is only visible to you and authorized administrators.';status.classList.toggle('is-error',tooLarge);}
  }
  const key=el.dataset.search;if(key){clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>filterTable(key,el.value),180);}
  const documentForm=el.closest('.document-editor-form');if(documentForm)updateDocumentPreview(documentForm);
}
function filterTable(key, value){
  const selector={products:'.table-card tbody tr',inventory:'.table-card tbody tr',customers:'.table-card tbody tr',suppliers:'.table-card tbody tr',invoices:'.table-card tbody tr',expenses:'.table-card tbody tr','pos-products':'#pos-product-grid .pos-product'}[key];if(!selector)return;
  document.querySelectorAll(selector).forEach(row=>{row.style.display=row.textContent.toLowerCase().includes(value.toLowerCase())?'':'none';});
}
export function handleChange(el) {
  if(el.matches('[data-receipt-file]'))handleInput(el);
  if(el.matches('.line-product')){
    const row=el.closest('.line-row');const opt=el.selectedOptions[0];const name=row.querySelector('.line-name');const price=row.querySelector('.line-price');if(el.value){name.value=opt.dataset.name||'';name.style.display='none';name.required=false;if(price)price.value=opt.dataset.price||0;}else{name.style.display='';name.required=true;name.value='';if(price)price.value=0;}
  }
  if(el.name==='report_type'){const p=new URLSearchParams(location.search);p.set('type',el.value);navigate(`/reports?${p}`);}
  if(el.name==='period'){const type=new URLSearchParams(location.search).get('type')||'sales';navigate(`/reports?type=${type}&period=${el.value}`);}
  if(el.name==='paid_amount')el.dataset.touched='1';
  const documentForm=el.closest('.document-editor-form');if(documentForm)updateDocumentPreview(documentForm);
}
